-- Generated by scripts/build_compiled.py from src/fraudrules/rules/payee-fraud/pf-001-payee-change-then-payment.yaml. Do not edit.
-- PF-001 Payment to a payee whose bank details changed in the last three days
SELECT DISTINCT 'PF-001' AS rule_id, 'transactions' AS anchor_table, s1.id AS anchor_id
FROM transactions AS s1
JOIN events AS s0 ON s0.customer_id = s1.customer_id AND s0.ts < s1.ts AND s0.ts > s1.ts - 259200 AND s0.payee_id = s1.counterparty_id AND (s0.event_type IN ('payee_added', 'payee_changed') AND s0.outcome = 'success')
WHERE (s1.direction = 'out' AND s1.channel IN ('wire', 'ach', 'rtp') AND s1.amount_cents >= 500000);
